    if (!path.isEmpty()) {
        // Split the path into an array of path segments
        String[] segments = path.split("/");

        // Add each path segment to the list, decoding if specified
        for (int i = 0; i < segments.length; i++) {
            String segment = segments[i];
            if (decode) {
                segment = URLDecoder.decode(segment, DEFAULT_ENCODING);
            }
