            // Check if the thread ID is in the time range
            int threadId = Integer.parseInt(columns[0]);
            ProfileAnalyzeTimeRange timeRange = timeRanges.get(threadId);
            if (timeRange != null && timeRange.getStartTime() < columns[1] && columns[1] < timeRange.getEndTime()) {
                // Add a new snapshot for the thread
